  'tips.chatQuiz.nudge': 'Pogosteje pomeni več vaje. Poskusi 1 od 3 ali vsako sporočilo.',
  'tips.chatQuiz.summary': 'Včasih pišeš v {native}, ker nisi prepričan v {practice} ali se ti mudi. Hiter kviz v klepetu spremeni to sporočilo v vajo za {practice}.',
  'tips.chatQuiz.title': 'Vadi {practice}, tudi ko pišeš v {native}',
